// Frutas de Panda Cha: caen por los lados mientras la boca está abierta
const fruitEvery = [140, 420];   // cada cuántos ms sale una (rápido, lento). Más abierta la boca = más rápido
const fruitLife = [2600, 3800];  // cuánto tarda en caer (ms). Más alto = caen más lento
const fruitSize = 0.32;          // tamaño de las frutas (1 = ancho de la cara)
const sideMin = 0.7;             // qué tan cerca de la cara pueden caer (0.5 = borde de la cara)
const sideMax = 1.15;            // qué tan lejos pueden caer
const fruitTop = 1.2;            // altura desde donde salen
const fruitBottom = -1.1;        // altura hasta donde caen
const fruitKinds = ['fresa', 'limon', 'liche', 'durazno', 'hoja', 'hoja']; // las hojas salen el doble

// Corazoncitos que cambian de color mientras la boca está abierta
const heartEvery = [350, 700];   // cada cuántos ms sale un corazón
const heartSize = [0.09, 0.17];
const colorSpeed = 2500;         // ms que tarda en dar la vuelta a todos los colores. Más bajo = cambia más rápido


// Mordisco: con la boca abierta y los ojos cerrados aparece una fruta al azar con un mordisco
const biteKinds = ['fresa', 'limon', 'liche', 'durazno']; // una distinta cada vez
const biteSize = 0.55;          // tamaño de la fruta mordida (1 = ancho de la cara)
const biteMouthY = -0.5;        // altura de la boca (más bajo = más abajo en la cara)
const biteMouthZ = 0.45;        // qué tan al frente de la cara queda
const biteIn = 250;             // ms que tarda en aparecer
const biteOut = 220;            // ms que tarda en desaparecer
const biteStay = 4500;          // ms que se queda la fruta con su frase (aunque abras los ojos)
const eyesClosedAt = 0.6;       // qué tan cerrados deben estar los ojos (0 a 1)
const eyesHold = 400;           // ms con los ojos cerrados para que cuente (así un parpadeo normal no la activa)

// Frase de la fruta (abajo de la cara)
const phraseY = -1.15;          // altura de la frase (más bajo = más abajo)
const phraseZ = 0.3;
const phraseWidth = 1.9;        // ancho de la frase (1 = ancho de la cara)
const phraseDelay = 450;        // ms después de la fruta para que aparezca la frase

const fruitInfo = {
	limon: {
		color: '#f2b800',
		phrases: [
			'Que nada te apague la chispa',
			'Tu chispa le da vida al día',
			'Tu buena energía se nota',
			'Hoy el mundo te sonríe de vuelta'
		]
	},
	fresa: {
		color: '#ea2f45',
		phrases: [
			'Eres dulzura en todo lo que haces',
			'Tu cariño alegra a quien te rodea',
			'Que hoy te pasen cosas bonitas',
			'Tu forma de querer hace todo más lindo'
		]
	},
	liche: {
		color: '#e63a63',
		phrases: [
			'Nunca pierdas tu alegría, tu sonrisa y tu forma de ser',
			'Eres muy especial, más de lo que imaginas',
			'Que hoy todo fluya bonito',
			'Hoy brillas con calma y elegancia'
		]
	},
	durazno: {
		color: '#ff8f75',
		phrases: [
			'Tu calidez se siente a kilómetros',
			'Qué bonito coincidir contigo',
			'Tu presencia hace el día más cálido',
			'Que hoy recibas todo lo bonito que das'
		]
	}
};

// Sonidos
const soundFruits = loadSound('assets/frutas.mp3');    // suena al abrir la boca y se repite sin parar mientras la boca siga abierta
const soundBite = loadSound('assets/mordisco.mp3');    // suena cada vez que aparece una fruta nueva en la boca

const maxItems = 26;
let mouthIsOpen = false;
let clock = 0;
let fruitTimer = 0;
let heartTimer = 0;
let biteMesh = null;
let biteProgress = 0;
let biteLast = null;
let biteHold = 0;
let biteAge = 0;
let phraseMesh = null;
let eyesTimer = 0;
let eyesTriggered = false;
const active = [];
const free = [];
const textures = {};

// ---- Sonidos (los mp3 están en la carpeta assets) ----

function loadSound(file) {
	try {
		const audio = new Audio(file);
		audio.preload = 'auto';
		return audio;
	} catch (e) {
		return null;
	}
}

function playSound(audio) {
	if (!audio) return;
	try {
		audio.currentTime = 0;
		const result = audio.play();
		if (result && result.catch) result.catch(() => {});
	} catch (e) {}
}

function stopSound(audio) {
	if (!audio) return;
	try {
		audio.pause();
		audio.currentTime = 0;
	} catch (e) {}
}

function random(a, b) {
	return a + Math.random() * (b - a);
}

function easeOutBack(x) {
	const c1 = 1.70158;
	const c3 = c1 + 1;
	return 1 + c3 * Math.pow(x - 1, 3) + c1 * Math.pow(x - 1, 2);
}

// ---- Dibujo de cada fruta (todo se dibuja con código, no hay imágenes) ----

function leafPath(ctx, s) {
	ctx.beginPath();
	ctx.moveTo(0, -0.46 * s);
	ctx.bezierCurveTo(0.36 * s, -0.2 * s, 0.34 * s, 0.25 * s, 0, 0.46 * s);
	ctx.bezierCurveTo(-0.3 * s, 0.25 * s, -0.32 * s, -0.2 * s, 0, -0.46 * s);
	ctx.closePath();
}

function drawLeaf(ctx, s) {
	const g = ctx.createLinearGradient(-0.3 * s, 0, 0.3 * s, 0);
	g.addColorStop(0, '#7edc62');
	g.addColorStop(0.55, '#2fa63a');
	g.addColorStop(1, '#17722a');
	leafPath(ctx, s);
	ctx.fillStyle = g;
	ctx.fill();
	ctx.lineWidth = 0.014 * s;
	ctx.strokeStyle = '#14661f';
	ctx.stroke();
	// Nervadura y venas
	ctx.strokeStyle = 'rgba(200, 255, 170, 0.75)';
	ctx.lineWidth = 0.022 * s;
	ctx.lineCap = 'round';
	ctx.beginPath();
	ctx.moveTo(0, 0.44 * s);
	ctx.quadraticCurveTo(0.03 * s, 0, 0, -0.4 * s);
	ctx.stroke();
	ctx.lineWidth = 0.011 * s;
	for (let k = -2; k <= 2; k++) {
		const y = k * 0.13 * s;
		ctx.beginPath();
		ctx.moveTo(0.01 * s, y + 0.06 * s);
		ctx.lineTo(0.17 * s, y - 0.04 * s);
		ctx.moveTo(0.01 * s, y + 0.06 * s);
		ctx.lineTo(-0.15 * s, y - 0.04 * s);
		ctx.stroke();
	}
	// Brillo
	ctx.fillStyle = 'rgba(255, 255, 255, 0.28)';
	ctx.beginPath();
	ctx.ellipse(-0.1 * s, -0.12 * s, 0.045 * s, 0.17 * s, 0.15, 0, Math.PI * 2);
	ctx.fill();
}

function strawberryPath(ctx, s) {
	ctx.beginPath();
	ctx.moveTo(0, 0.44 * s);
	ctx.bezierCurveTo(0.52 * s, 0.15 * s, 0.48 * s, -0.28 * s, 0.2 * s, -0.3 * s);
	ctx.quadraticCurveTo(0, -0.31 * s, -0.2 * s, -0.3 * s);
	ctx.bezierCurveTo(-0.48 * s, -0.28 * s, -0.52 * s, 0.15 * s, 0, 0.44 * s);
	ctx.closePath();
}

function drawStrawberry(ctx, s) {
	ctx.translate(0, 0.04 * s);
	const g = ctx.createRadialGradient(-0.12 * s, -0.08 * s, 0.03 * s, 0, 0.05 * s, 0.5 * s);
	g.addColorStop(0, '#ff6f6f');
	g.addColorStop(0.55, '#ea2f45');
	g.addColorStop(1, '#b8142e');
	strawberryPath(ctx, s);
	ctx.fillStyle = g;
	ctx.fill();
	// Semillas
	ctx.save();
	strawberryPath(ctx, s);
	ctx.clip();
	ctx.fillStyle = '#ffe6b3';
	for (let row = 0; row < 6; row++) {
		const y = -0.16 * s + row * 0.115 * s;
		const count = Math.max(1, 4 - Math.floor(row / 2));
		for (let i = 0; i < count; i++) {
			const x = (i - (count - 1) / 2) * 0.17 * s;
			ctx.beginPath();
			ctx.ellipse(x, y, 0.017 * s, 0.03 * s, 0.25 * x / s, 0, Math.PI * 2);
			ctx.fill();
		}
	}
	ctx.restore();
	// Brillo
	ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
	ctx.beginPath();
	ctx.ellipse(-0.2 * s, -0.08 * s, 0.05 * s, 0.13 * s, 0.35, 0, Math.PI * 2);
	ctx.fill();
	// Hojitas de arriba
	ctx.save();
	ctx.translate(0, -0.28 * s);
	for (const angle of [-2.6, -2.05, -1.57, -1.08, -0.54]) {
		ctx.save();
		ctx.rotate(angle + Math.PI / 2);
		ctx.beginPath();
		ctx.moveTo(0, 0);
		ctx.quadraticCurveTo(0.1 * s, -0.1 * s, 0, -0.26 * s);
		ctx.quadraticCurveTo(-0.1 * s, -0.1 * s, 0, 0);
		const lg = ctx.createLinearGradient(0, 0, 0, -0.26 * s);
		lg.addColorStop(0, '#1f8a2c');
		lg.addColorStop(1, '#5fc24a');
		ctx.fillStyle = lg;
		ctx.fill();
		ctx.restore();
	}
	ctx.restore();
}

function drawLemon(ctx, s) {
	ctx.rotate(-0.5);
	let g = ctx.createLinearGradient(-0.4 * s, -0.3 * s, 0.4 * s, 0.3 * s);
	g.addColorStop(0, '#ffe46b');
	g.addColorStop(1, '#f2a100');
	ctx.fillStyle = g;
	ctx.beginPath();
	ctx.ellipse(0, 0, 0.46 * s, 0.34 * s, 0, 0, Math.PI * 2);
	ctx.fill();
	ctx.fillStyle = '#fff5cf';
	ctx.beginPath();
	ctx.ellipse(0, 0, 0.395 * s, 0.28 * s, 0, 0, Math.PI * 2);
	ctx.fill();
	g = ctx.createRadialGradient(0, 0, 0.02 * s, 0, 0, 0.34 * s);
	g.addColorStop(0, '#ffe98a');
	g.addColorStop(1, '#ffc81f');
	ctx.fillStyle = g;
	ctx.beginPath();
	ctx.ellipse(0, 0, 0.35 * s, 0.235 * s, 0, 0, Math.PI * 2);
	ctx.fill();
	// Gajos
	ctx.strokeStyle = '#fff3c4';
	ctx.lineWidth = 0.018 * s;
	ctx.lineCap = 'round';
	for (let k = 0; k < 10; k++) {
		const a = (k / 10) * Math.PI * 2;
		ctx.beginPath();
		ctx.moveTo(Math.cos(a) * 0.05 * s, Math.sin(a) * 0.035 * s);
		ctx.lineTo(Math.cos(a) * 0.34 * s, Math.sin(a) * 0.228 * s);
		ctx.stroke();
	}
	ctx.fillStyle = '#fff3c4';
	ctx.beginPath();
	ctx.ellipse(0, 0, 0.035 * s, 0.025 * s, 0, 0, Math.PI * 2);
	ctx.fill();
	// Brillo del borde
	ctx.strokeStyle = 'rgba(255, 255, 255, 0.55)';
	ctx.lineWidth = 0.03 * s;
	ctx.beginPath();
	ctx.ellipse(0, 0, 0.43 * s, 0.31 * s, 0, Math.PI * 1.05, Math.PI * 1.45);
	ctx.stroke();
}

function drawLychee(ctx, s, whole) {
	const r = 0.43 * s;
	const g = ctx.createRadialGradient(-0.12 * s, -0.14 * s, 0.03 * s, 0, 0, r);
	g.addColorStop(0, '#ff7d9b');
	g.addColorStop(0.6, '#e63a63');
	g.addColorStop(1, '#b81a47');
	ctx.fillStyle = g;
	ctx.beginPath();
	ctx.arc(0, 0, r, 0, Math.PI * 2);
	ctx.fill();
	// Textura de puntitos
	ctx.save();
	ctx.beginPath();
	ctx.arc(0, 0, r, 0, Math.PI * 2);
	ctx.clip();
	const step = 0.085 * s;
	for (let row = -6; row <= 6; row++) {
		for (let col = -6; col <= 6; col++) {
			const x = col * step + (row % 2 ? step / 2 : 0);
			const y = row * step * 0.87;
			ctx.fillStyle = 'rgba(110, 0, 35, 0.28)';
			ctx.beginPath();
			ctx.arc(x + 0.012 * s, y + 0.014 * s, 0.036 * s, 0, Math.PI * 2);
			ctx.fill();
			ctx.fillStyle = 'rgba(255, 190, 205, 0.38)';
			ctx.beginPath();
			ctx.arc(x - 0.006 * s, y - 0.008 * s, 0.024 * s, 0, Math.PI * 2);
			ctx.fill();
		}
	}
	ctx.restore();
	if (whole) return;
	// Pulpa blanca
	ctx.fillStyle = '#c21f4b';
	ctx.beginPath();
	ctx.ellipse(0.1 * s, -0.04 * s, 0.285 * s, 0.26 * s, -0.3, 0, Math.PI * 2);
	ctx.fill();
	const pg = ctx.createRadialGradient(0.04 * s, -0.1 * s, 0.02 * s, 0.1 * s, -0.04 * s, 0.27 * s);
	pg.addColorStop(0, '#ffffff');
	pg.addColorStop(0.7, '#f2eeea');
	pg.addColorStop(1, '#d9d2ce');
	ctx.fillStyle = pg;
	ctx.beginPath();
	ctx.ellipse(0.1 * s, -0.04 * s, 0.25 * s, 0.225 * s, -0.3, 0, Math.PI * 2);
	ctx.fill();
	ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
	ctx.beginPath();
	ctx.ellipse(0.02 * s, -0.12 * s, 0.05 * s, 0.03 * s, -0.5, 0, Math.PI * 2);
	ctx.fill();
}

function drawPeach(ctx, s) {
	ctx.translate(-0.02 * s, 0.1 * s);
	ctx.scale(0.88, 0.88);
	const g = ctx.createRadialGradient(-0.12 * s, -0.12 * s, 0.03 * s, 0, 0.02 * s, 0.5 * s);
	g.addColorStop(0, '#ffe3ab');
	g.addColorStop(0.5, '#ffb08f');
	g.addColorStop(1, '#ff7482');
	ctx.fillStyle = g;
	ctx.beginPath();
	ctx.moveTo(0, -0.32 * s);
	ctx.bezierCurveTo(0.2 * s, -0.46 * s, 0.5 * s, -0.3 * s, 0.44 * s, 0.05 * s);
	ctx.bezierCurveTo(0.4 * s, 0.34 * s, 0.14 * s, 0.46 * s, 0, 0.42 * s);
	ctx.bezierCurveTo(-0.14 * s, 0.46 * s, -0.4 * s, 0.34 * s, -0.44 * s, 0.05 * s);
	ctx.bezierCurveTo(-0.5 * s, -0.3 * s, -0.2 * s, -0.46 * s, 0, -0.32 * s);
	ctx.closePath();
	ctx.fill();
	// Línea central
	ctx.strokeStyle = 'rgba(210, 70, 90, 0.4)';
	ctx.lineWidth = 0.022 * s;
	ctx.lineCap = 'round';
	ctx.beginPath();
	ctx.moveTo(0, -0.3 * s);
	ctx.bezierCurveTo(0.1 * s, -0.12 * s, 0.1 * s, 0.14 * s, 0.02 * s, 0.38 * s);
	ctx.stroke();
	// Brillo
	ctx.fillStyle = 'rgba(255, 255, 255, 0.32)';
	ctx.beginPath();
	ctx.ellipse(-0.22 * s, -0.08 * s, 0.05 * s, 0.13 * s, 0.4, 0, Math.PI * 2);
	ctx.fill();
	// Tallito y hojita
	ctx.strokeStyle = '#7a4a2a';
	ctx.lineWidth = 0.035 * s;
	ctx.beginPath();
	ctx.moveTo(0, -0.32 * s);
	ctx.lineTo(0.02 * s, -0.43 * s);
	ctx.stroke();
	ctx.save();
	ctx.translate(0.17 * s, -0.4 * s);
	ctx.rotate(1.0);
	ctx.translate(0, -0.1 * s);
	drawLeaf(ctx, 0.36 * s);
	ctx.restore();
}

function drawHeart(ctx, s) {
	ctx.translate(-0.5 * s, -0.5 * s);
	const w = s;
	ctx.beginPath();
	ctx.moveTo(w * 0.5, w * 0.88);
	ctx.bezierCurveTo(w * 0.1, w * 0.55, w * 0.05, w * 0.2, w * 0.275, w * 0.15);
	ctx.bezierCurveTo(w * 0.4, w * 0.1, w * 0.5, w * 0.25, w * 0.5, w * 0.32);
	ctx.bezierCurveTo(w * 0.5, w * 0.25, w * 0.6, w * 0.1, w * 0.725, w * 0.15);
	ctx.bezierCurveTo(w * 0.95, w * 0.2, w * 0.9, w * 0.55, w * 0.5, w * 0.88);
	ctx.closePath();
	ctx.fillStyle = '#ffffff';
	ctx.fill();
	ctx.save();
	ctx.clip();
	ctx.fillStyle = 'rgba(0, 0, 0, 0.1)';
	ctx.beginPath();
	ctx.ellipse(w * 0.66, w * 0.6, w * 0.16, w * 0.28, -0.5, 0, Math.PI * 2);
	ctx.fill();
	ctx.restore();
}

const drawers = { fresa: drawStrawberry, limon: drawLemon, liche: drawLychee, durazno: drawPeach, hoja: drawLeaf, corazon: drawHeart };

function getTexture(kind) {
	if (!textures[kind]) {
		const size = 192;
		const canvas = document.createElement('canvas');
		canvas.width = canvas.height = size;
		const ctx = canvas.getContext('2d');
		ctx.translate(size / 2, size / 2);
		if (kind === 'hoja') ctx.rotate(0.6);
		drawers[kind](ctx, size);
		const texture = new THREE.CanvasTexture(canvas);
		texture.colorSpace = THREE.SRGBColorSpace;
		textures[kind] = texture;
	}
	return textures[kind];
}

// ---- Objetos que caen ----

function spawn(kind, x, size, z) {
	if (active.length >= maxItems) return;

	let mesh = free.pop();
	if (!mesh) {
		mesh = new THREE.Mesh(
			new THREE.PlaneGeometry(1, 1),
			new THREE.MeshBasicMaterial({ transparent: true, depthWrite: false, side: THREE.DoubleSide })
		);
		mesh.renderOrder = 4;
		scene.add(mesh);
	}

	mesh.material.map = getTexture(kind);
	mesh.material.color.set(0xffffff);
	mesh.material.needsUpdate = true;
	mesh.visible = true;

	active.push({
		mesh, kind, x, size, z,
		age: 0,
		life: random(fruitLife[0], fruitLife[1]),
		sway: random(0.02, 0.07),
		phase: Math.random() * Math.PI * 2,
		spin0: random(-0.6, 0.6),
		spin: random(-0.0012, 0.0012)
	});
}

function spawnFruit() {
	const kind = fruitKinds[Math.floor(Math.random() * fruitKinds.length)];
	const side = Math.random() < 0.5 ? -1 : 1;
	const size = fruitSize * random(0.8, 1.15) * (kind === 'hoja' ? 0.85 : 1);
	spawn(kind, side * random(sideMin, sideMax), size, 0.2);
}

function spawnHeart() {
	spawn('corazon', random(-0.9, 0.9), random(heartSize[0], heartSize[1]), 0.5);
}

function updateItems(dt) {
	const hue = (clock / colorSpeed) % 1;

	for (let i = active.length - 1; i >= 0; i--) {
		const item = active[i];
		item.age += dt;
		const t = item.age / item.life;

		if (t >= 1) {
			item.mesh.visible = false;
			free.push(item.mesh);
			active.splice(i, 1);
			continue;
		}

		const appear = Math.min(1, item.age / 250);
		const fadeOut = Math.min(1, (item.life - item.age) / 450);
		const fall = 0.6 * t + 0.4 * t * t;

		item.mesh.position.set(
			item.x + Math.sin(item.age / 500 + item.phase) * item.sway,
			fruitTop + (fruitBottom - fruitTop) * fall,
			item.z
		);
		item.mesh.rotation.z = item.spin0 + item.age * item.spin;
		item.mesh.scale.setScalar(item.size * Math.max(easeOutBack(appear), 0.001));
		item.mesh.material.opacity = Math.min(appear, fadeOut);

		// Los corazones cambian de color mientras la boca está abierta
		if (item.kind === 'corazon') item.mesh.material.color.setHSL(hue, 0.9, 0.72);
	}
}


// ---- Fruta mordida en la boca ----

// El lichi se dibuja entero y el mordisco deja ver la pulpa por dentro. El limón sale como rodaja, sin mordisco
const wholeDrawers = {
	liche: (ctx, s) => drawLychee(ctx, s, true)
};
const fleshColors = { liche: '#fbf5ee' };
const noBite = ['limon'];

function makeBiteTexture(kind) {
	const size = 192;
	const canvas = document.createElement('canvas');
	canvas.width = canvas.height = size;
	const ctx = canvas.getContext('2d');
	ctx.translate(size / 2, size / 2);
	(wholeDrawers[kind] || drawers[kind])(ctx, size);
	ctx.setTransform(1, 0, 0, 1, 0, 0);

	if (noBite.includes(kind)) {
		const plain = new THREE.CanvasTexture(canvas);
		plain.colorSpace = THREE.SRGBColorSpace;
		return plain;
	}

	// El mordisco: tres círculos que se juntan, en una esquina al azar
	const angle = random(-Math.PI * 0.85, -Math.PI * 0.15);
	const dx = Math.cos(angle), dy = Math.sin(angle);
	const reach = size * 0.43;
	const bites = [[0, 0.2], [-0.17, 0.11], [0.17, 0.11]];
	const spots = bites.map(([side, radius]) => ({
		x: size / 2 + dx * reach - dy * side * size,
		y: size / 2 + dy * reach + dx * side * size,
		r: radius * size
	}));

	const flesh = fleshColors[kind];
	if (flesh) {
		// Pulpa: se pinta solo sobre la fruta
		ctx.globalCompositeOperation = 'source-atop';
		ctx.fillStyle = flesh;
		for (const c of spots) {
			ctx.beginPath();
			ctx.arc(c.x, c.y, c.r, 0, Math.PI * 2);
			ctx.fill();
		}
	}
	ctx.globalCompositeOperation = 'destination-out';
	for (const c of spots) {
		const shift = flesh ? c.r * 0.22 : 0;
		const radius = flesh ? c.r * 0.8 : c.r;
		ctx.beginPath();
		ctx.arc(c.x + dx * shift, c.y + dy * shift, radius, 0, Math.PI * 2);
		ctx.fill();
	}
	ctx.globalCompositeOperation = 'source-over';

	const texture = new THREE.CanvasTexture(canvas);
	texture.colorSpace = THREE.SRGBColorSpace;
	return texture;
}

function makePhraseTexture(info, phrase) {
	const w = 1024, h = 300;
	const canvas = document.createElement('canvas');
	canvas.width = w;
	canvas.height = h;
	const ctx = canvas.getContext('2d');

	// Tarjetita redondeada
	const r = 70, m = 10;
	ctx.beginPath();
	ctx.moveTo(m + r, m);
	ctx.arcTo(w - m, m, w - m, h - m, r);
	ctx.arcTo(w - m, h - m, m, h - m, r);
	ctx.arcTo(m, h - m, m, m, r);
	ctx.arcTo(m, m, w - m, m, r);
	ctx.closePath();
	ctx.fillStyle = 'rgba(255, 255, 255, 0.94)';
	ctx.fill();
	ctx.lineWidth = 12;
	ctx.strokeStyle = info.color;
	ctx.stroke();

	ctx.textAlign = 'center';
	ctx.textBaseline = 'middle';
	ctx.fillStyle = '#5a2a3a';
	const fontOf = size => 'bold ' + size + 'px "Trebuchet MS", "Arial Rounded MT Bold", Arial, sans-serif';
	const maxWidth = w - 120;
	ctx.font = fontOf(66);
	if (ctx.measureText(phrase).width <= maxWidth) {
		ctx.fillText(phrase, w / 2, h / 2);
	} else {
		// Frase larga: se parte en dos renglones, cortando por el espacio más cercano al centro
		let cut = phrase.indexOf(' ');
		for (let i = 0; i < phrase.length; i++) {
			if (phrase[i] === ' ' && Math.abs(i - phrase.length / 2) < Math.abs(cut - phrase.length / 2)) cut = i;
		}
		const lines = [phrase.slice(0, cut), phrase.slice(cut + 1)];
		let size = 58;
		ctx.font = fontOf(size);
		while (Math.max(ctx.measureText(lines[0]).width, ctx.measureText(lines[1]).width) > maxWidth && size > 30) {
			size -= 2;
			ctx.font = fontOf(size);
		}
		ctx.fillText(lines[0], w / 2, h / 2 - size * 0.62);
		ctx.fillText(lines[1], w / 2, h / 2 + size * 0.62);
	}

	const texture = new THREE.CanvasTexture(canvas);
	texture.colorSpace = THREE.SRGBColorSpace;
	return texture;
}

function startBite() {
	// Una fruta distinta a la anterior, al azar
	let options = biteKinds.filter(k => k !== biteLast);
	if (options.length === 0) options = biteKinds;
	const kind = options[Math.floor(Math.random() * options.length)];
	biteLast = kind;

	if (!biteMesh) {
		biteMesh = new THREE.Mesh(
			new THREE.PlaneGeometry(1, 1),
			new THREE.MeshBasicMaterial({ transparent: true, depthWrite: false, side: THREE.DoubleSide })
		);
		biteMesh.renderOrder = 5;
		biteMesh.visible = false;
		scene.add(biteMesh);

		phraseMesh = new THREE.Mesh(
			new THREE.PlaneGeometry(1, 300 / 1024),
			new THREE.MeshBasicMaterial({ transparent: true, depthWrite: false, side: THREE.DoubleSide })
		);
		phraseMesh.renderOrder = 6;
		phraseMesh.visible = false;
		scene.add(phraseMesh);
	}
	if (biteMesh.material.map) biteMesh.material.map.dispose();
	biteMesh.material.map = makeBiteTexture(kind);
	biteMesh.material.needsUpdate = true;
	biteMesh.rotation.z = random(-0.3, 0.3);

	// La frase: una al azar de las de esa fruta
	const info = fruitInfo[kind];
	const phrase = info.phrases[Math.floor(Math.random() * info.phrases.length)];
	if (phraseMesh.material.map) phraseMesh.material.map.dispose();
	phraseMesh.material.map = makePhraseTexture(info, phrase);
	phraseMesh.material.needsUpdate = true;

	biteProgress = 0;
	biteAge = 0;
	biteHold = biteStay;
	playSound(soundBite);
}

function updateBite(dt) {
	if (!biteMesh) return;
	const show = biteHold > 0;
	if (show) {
		biteHold -= dt;
		biteAge += dt;
	}
	const step = dt / (show ? biteIn : biteOut);
	biteProgress = Math.min(1, Math.max(0, biteProgress + (show ? step : -step)));

	biteMesh.visible = biteProgress > 0;
	if (!biteMesh.visible) {
		phraseMesh.visible = false;
		return;
	}

	const jaw = typeof face !== 'undefined' && face ? face.jawOpen : 0.5;
	biteMesh.position.set(0, biteMouthY - jaw * 0.1 + Math.sin(clock / 260) * 0.012, biteMouthZ);
	biteMesh.scale.setScalar(biteSize * Math.max(easeOutBack(biteProgress), 0.001));
	biteMesh.material.opacity = Math.min(1, biteProgress * 2);

	// La frase aparece un poquito después que la fruta
	const phraseP = Math.min(1, Math.max(0, (biteAge - phraseDelay) / 350));
	const phraseShow = show ? phraseP : biteProgress;
	phraseMesh.visible = phraseShow > 0;
	phraseMesh.position.set(0, phraseY + (1 - phraseShow) * -0.1, phraseZ);
	const phraseScale = phraseWidth * Math.max(easeOutBack(phraseShow), 0.001);
	phraseMesh.scale.set(-phraseScale, phraseScale, phraseScale); // x negativo para que el texto no salga en espejo
	phraseMesh.material.opacity = Math.min(1, phraseShow * 2);
}

function checkEyes(dt) {
	const closed = typeof face !== 'undefined' && face && Math.min(face.blinkLeft, face.blinkRight) > eyesClosedAt;
	if (!closed) {
		eyesTimer = 0;
		eyesTriggered = false;
	} else if (mouthIsOpen && !eyesTriggered) {
		eyesTimer += dt;
		if (eyesTimer >= eyesHold) {
			eyesTriggered = true;
			startBite();
		}
	}
}

// ---- Eventos de la cara ----

function update(event) {
	const dt = event.delta;
	clock += dt;

	if (mouthIsOpen) {
		const jaw = typeof face !== 'undefined' && face ? face.jawOpen : 0.5;
		const open = Math.min(1, Math.max(0, (jaw - 0.3) / 0.5)); // 0 = apenas abierta, 1 = muy abierta

		fruitTimer -= dt;
		if (fruitTimer <= 0) {
			spawnFruit();
			fruitTimer = (fruitEvery[1] + (fruitEvery[0] - fruitEvery[1]) * open) * random(0.8, 1.2);
		}

		heartTimer -= dt;
		if (heartTimer <= 0) {
			spawnHeart();
			heartTimer = random(heartEvery[0], heartEvery[1]);
		}
	}

	updateItems(dt);
	checkEyes(dt);
	updateBite(dt);
}

function mouthOpen(event) {
	mouthIsOpen = true;
	if (soundFruits) soundFruits.loop = true; // en bucle: al terminar vuelve a empezar
	playSound(soundFruits);
	fruitTimer = 0;
	heartTimer = 250;
}

function mouthClose(event) {
	mouthIsOpen = false;
	stopSound(soundFruits);
}

function stop(event) {
	stopSound(soundFruits);
	stopSound(soundBite);
}

function faceLost(event) {
	mouthIsOpen = false;
	biteHold = 0;
	stopSound(soundFruits);
	stopSound(soundBite);
	for (const item of active) item.age = item.life;
}

// Susto del panda: si cierras los dos ojos un rato y sonríes ligeramente aparece un panda
// que te asusta. Al abrir los ojos salen corazones, como si te dijera "te quiero".
const scareHold = 500;         // ms con los ojos cerrados y sonriendo ligeramente para que aparezca el panda. Un parpadeo normal dura ~150 ms
const scareSize = 1.9;         // tamaño del panda (1 = ancho de la cara)
const pandaAspect = 1.2281;    // ancho / alto de la imagen del panda (no lo cambies)
const scareOpacity = 0.55;     // 1 = sólido, 0.3 = muy transparente (igual que el panda del guiño)
const scareY = -0.1;           // altura del panda (más bajo = más abajo en la cara)
const scareZ = 0.7;            // qué tan al frente de la cara queda
const scareIn = 180;           // ms que tarda en aparecer (más bajo = susto más brusco)
const scareOut = 350;          // ms que tarda en irse
const loveStay = 1100;         // ms que se queda el panda después de abrir los ojos
const eyesClosedAt = 0.6;      // qué tan cerrados deben estar los ojos (0 a 1)
const eyesOpenAt = 0.4;        // qué tan abiertos deben estar para contar como abiertos
const smileOnAt = 0.2;         // qué tanto hay que sonreír (0 a 1). Más bajo = sonrisa más suave, más fácil de activar
const smileOffAt = 0.1;        // por debajo de esto deja de contar como sonrisa
const smileGrace = 300;        // ms que perdona si la cámara pierde la sonrisa un instante
const mouthOpenMax = 0.3;      // la boca debe estar cerrada (así no se mezcla con las frutas)

// Mensaje que aparece cuando abres los ojos
const sloganLines = ['Un día', 'más lindo'];  // los dos primeros renglones
const sloganLast = 'juntos';                  // último renglón (lleva el corazoncito)
const sloganColor = '#ff6f9c';                // color de las letras (rosado)
const sloganHeartColor = '#ff4d7d';
const sloganWidth = 1.0;       // ancho del mensaje (1 = ancho de la cara)
const sloganY = -1.0;          // altura del mensaje (más bajo = más abajo)
const sloganZ = 0.8;
const sloganDelay = 250;       // ms después de abrir los ojos para que aparezca
const sloganStay = 3200;       // ms que se queda el mensaje
const sloganFont = '"Caveat", "Bradley Hand", "Segoe Print", "Marker Felt", "Comic Sans MS", cursive';

// Corazones del "te quiero"
const loveCount = 26;          // cuántos corazones salen
const loveSize = [0.12, 0.24]; // tamaño (1 = ancho de la cara)
const loveSpeed = [0.7, 1.6];  // qué tan lejos llegan
const loveLife = [1400, 2200]; // cuánto duran (ms)
const loveColors = ['#ff6f91', '#ff8fab', '#ffb3c6', '#ff4d6d'];

// Sonido
const soundScare = loadSound('assets/susto.mp3');   // suena cuando aparece el panda

let phase = 'idle';            // idle = esperando, scared = panda visible, love = abriste los ojos
let closedTime = 0;
let openTimer = 0;
let eyesClosed = false;
let smiling = false;
let smileLost = 0;
let sloganAge = 99999;
let sloganMesh = null;
let sloganCanvas = null;
let sloganTexture = null;
let clock = 0;
let loveAge = 0;
let pandaProgress = 0;
let pandaMesh = null;
let pandaTexture = null;
const loveTextures = [];
const hearts = [];
const heartsFree = [];

// ---- Sonidos (los mp3 están en la carpeta assets) ----

function loadSound(file) {
	try {
		const audio = new Audio(file);
		audio.preload = 'auto';
		return audio;
	} catch (e) {
		return null;
	}
}

function playSound(audio) {
	if (!audio) return;
	try {
		audio.currentTime = 0;
		const result = audio.play();
		if (result && result.catch) result.catch(() => {});
	} catch (e) {}
}

function stopSound(audio) {
	if (!audio) return;
	try {
		audio.pause();
		audio.currentTime = 0;
	} catch (e) {}
}

function random(a, b) {
	return a + Math.random() * (b - a);
}

function clamp01(x) {
	return Math.min(1, Math.max(0, x));
}

function easeOutBack(x) {
	const c1 = 1.70158;
	const c3 = c1 + 1;
	return 1 + c3 * Math.pow(x - 1, 3) + c1 * Math.pow(x - 1, 2);
}

function easeOutCubic(x) {
	return 1 - Math.pow(1 - x, 3);
}

// ---- Corazones ----

function makeHeartTexture(color) {
	const size = 128;
	const canvas = document.createElement('canvas');
	canvas.width = canvas.height = size;
	const ctx = canvas.getContext('2d');
	const c = size / 2;
	ctx.fillStyle = color;
	ctx.beginPath();
	ctx.moveTo(c, size * 0.88);
	ctx.bezierCurveTo(size * 0.1, size * 0.55, size * 0.05, size * 0.2, c * 0.55, size * 0.15);
	ctx.bezierCurveTo(c * 0.8, size * 0.1, c, size * 0.25, c, size * 0.32);
	ctx.bezierCurveTo(c, size * 0.25, c * 1.2, size * 0.1, c * 1.45, size * 0.15);
	ctx.bezierCurveTo(size * 0.95, size * 0.2, size * 0.9, size * 0.55, c, size * 0.88);
	ctx.fill();
	ctx.fillStyle = 'rgba(255, 255, 255, 0.55)';
	ctx.beginPath();
	ctx.ellipse(size * 0.3, size * 0.3, size * 0.07, size * 0.045, -0.6, 0, Math.PI * 2);
	ctx.fill();
	const texture = new THREE.CanvasTexture(canvas);
	texture.colorSpace = THREE.SRGBColorSpace;
	return texture;
}

// ---- Panda ----

function createPanda() {
	if (pandaMesh) return;
	pandaTexture = new THREE.TextureLoader().load('data:image/png;base64,' + pandaImage);
	pandaTexture.colorSpace = THREE.SRGBColorSpace;

	pandaMesh = new THREE.Mesh(
		new THREE.PlaneGeometry(1, 1 / pandaAspect),
		new THREE.MeshBasicMaterial({ map: pandaTexture, transparent: true, depthWrite: false, side: THREE.DoubleSide })
	);
	pandaMesh.renderOrder = 8;
	pandaMesh.visible = false;
	scene.add(pandaMesh);
}

function start() {
	// Carga la imagen del panda y el mensaje desde el principio para que salgan sin retraso
	createPanda();
	createSlogan();
}

function startScare() {
	phase = 'scared';
	playSound(soundScare);
	createPanda();
	pandaProgress = 0;
}

function updatePanda(dt) {
	if (!pandaMesh) return;

	let show = phase === 'scared';
	if (phase === 'love') {
		loveAge += dt;
		show = loveAge < loveStay;
	}

	const step = dt / (show ? scareIn : scareOut);
	pandaProgress = clamp01(pandaProgress + (show ? step : -step));
	pandaMesh.visible = pandaProgress > 0;

	if (phase === 'love' && !show && pandaProgress === 0) phase = 'idle';
	if (!pandaMesh.visible) return;

	let shakeX = 0;
	let tilt = 0;
	if (phase === 'scared') {
		// Tiembla del susto
		shakeX = Math.sin(clock / 23) * 0.012;
		tilt = Math.sin(clock / 41) * 0.04;
	} else {
		tilt = Math.sin(clock / 220) * 0.05;
	}

	pandaMesh.position.set(shakeX, scareY, scareZ);
	pandaMesh.rotation.z = tilt;
	pandaMesh.scale.setScalar(scareSize * Math.max(easeOutBack(pandaProgress), 0.001));
	pandaMesh.material.opacity = scareOpacity * Math.min(1, pandaProgress * 2);
}

// ---- Mensaje ----

function heartPath(ctx, cx, cy, size) {
	const x = cx - size / 2, y = cy - size / 2;
	ctx.beginPath();
	ctx.moveTo(x + size * 0.5, y + size * 0.9);
	ctx.bezierCurveTo(x + size * 0.1, y + size * 0.58, x + size * 0.02, y + size * 0.2, x + size * 0.27, y + size * 0.14);
	ctx.bezierCurveTo(x + size * 0.4, y + size * 0.1, x + size * 0.5, y + size * 0.24, x + size * 0.5, y + size * 0.32);
	ctx.bezierCurveTo(x + size * 0.5, y + size * 0.24, x + size * 0.6, y + size * 0.1, x + size * 0.73, y + size * 0.14);
	ctx.bezierCurveTo(x + size * 0.98, y + size * 0.2, x + size * 0.9, y + size * 0.58, x + size * 0.5, y + size * 0.9);
	ctx.closePath();
}

function drawSlogan() {
	const w = sloganCanvas.width, h = sloganCanvas.height;
	const ctx = sloganCanvas.getContext('2d');
	ctx.clearRect(0, 0, w, h);
	ctx.save();
	ctx.translate(w / 2, h / 2);
	ctx.rotate(-0.06);
	ctx.textAlign = 'center';
	ctx.textBaseline = 'middle';
	ctx.font = 'bold 150px ' + sloganFont;
	ctx.lineJoin = 'round';
	ctx.lineWidth = 24;
	ctx.strokeStyle = 'rgba(255, 255, 255, 0.95)';
	ctx.fillStyle = sloganColor;
	ctx.shadowColor = 'rgba(150, 20, 70, 0.25)';
	ctx.shadowBlur = 14;

	const lineHeight = 165;
	const lines = sloganLines.concat([sloganLast]);
	const firstY = -((lines.length - 1) * lineHeight) / 2;
	lines.forEach((line, i) => {
		const y = firstY + i * lineHeight;
		const isLast = i === lines.length - 1;
		const textWidth = ctx.measureText(line).width;
		const x = isLast ? -60 : 0;
		ctx.strokeText(line, x, y);
		ctx.fillText(line, x, y);
		if (isLast) {
			// Corazoncito al final de "juntos"
			const hx = x + textWidth / 2 + 80;
			heartPath(ctx, hx, y + 8, 115);
			ctx.lineWidth = 24;
			ctx.stroke();
			ctx.fillStyle = sloganHeartColor;
			ctx.fill();
			ctx.fillStyle = sloganColor;
		}
	});
	ctx.restore();
}

function createSlogan() {
	if (sloganMesh) return;
	sloganCanvas = document.createElement('canvas');
	sloganCanvas.width = 800;
	sloganCanvas.height = 600;
	drawSlogan();
	sloganTexture = new THREE.CanvasTexture(sloganCanvas);
	sloganTexture.colorSpace = THREE.SRGBColorSpace;

	sloganMesh = new THREE.Mesh(
		new THREE.PlaneGeometry(1, sloganCanvas.height / sloganCanvas.width),
		new THREE.MeshBasicMaterial({ map: sloganTexture, transparent: true, depthWrite: false, side: THREE.DoubleSide })
	);
	sloganMesh.renderOrder = 7;
	sloganMesh.visible = false;
	scene.add(sloganMesh);

	// Letra a mano (Caveat). Si no hay internet se usa una letra a mano del computador
	try {
		if (!document.getElementById('slogan-font')) {
			const link = document.createElement('link');
			link.id = 'slogan-font';
			link.rel = 'stylesheet';
			link.href = 'https://fonts.googleapis.com/css2?family=Caveat:wght@700&display=swap';
			document.head.appendChild(link);
		}
		document.fonts.load('700 150px Caveat').then(() => {
			drawSlogan();
			sloganTexture.needsUpdate = true;
		}).catch(() => {});
	} catch (e) {}
}

function updateSlogan(dt) {
	if (!sloganMesh) return;
	sloganAge += dt;
	const t = sloganAge - sloganDelay;
	if (t < 0 || t > sloganStay) {
		sloganMesh.visible = false;
		return;
	}
	const appear = clamp01(t / 350);
	const fadeOut = clamp01((sloganStay - t) / 450);
	sloganMesh.visible = true;
	sloganMesh.position.set(0, sloganY + Math.sin(clock / 400) * 0.015, sloganZ);
	// x negativo para que el texto no salga en espejo
	const scale = sloganWidth * Math.max(easeOutBack(appear), 0.001);
	sloganMesh.scale.set(-scale, scale, scale);
	sloganMesh.material.opacity = Math.min(appear * 2, fadeOut, 1);
}

// ---- Corazones del te quiero ----

function startLove() {
	phase = 'love';
	loveAge = 0;
	createSlogan();
	sloganAge = 0;
	if (loveTextures.length === 0) {
		for (const color of loveColors) loveTextures.push(makeHeartTexture(color));
	}

	for (let i = 0; i < loveCount; i++) {
		let mesh = heartsFree.pop();
		if (!mesh) {
			mesh = new THREE.Mesh(
				new THREE.PlaneGeometry(1, 1),
				new THREE.MeshBasicMaterial({ transparent: true, depthWrite: false, side: THREE.DoubleSide })
			);
			mesh.renderOrder = 9;
			scene.add(mesh);
		}
		mesh.material.map = loveTextures[Math.floor(Math.random() * loveTextures.length)];
		mesh.material.needsUpdate = true;
		mesh.visible = false;

		hearts.push({
			mesh,
			delay: random(0, 450),
			age: 0,
			life: random(loveLife[0], loveLife[1]),
			angle: random(0, Math.PI * 2),
			distance: random(loveSpeed[0], loveSpeed[1]),
			size: random(loveSize[0], loveSize[1]),
			phase: Math.random() * Math.PI * 2
		});
	}
}

function updateHearts(dt) {
	for (let i = hearts.length - 1; i >= 0; i--) {
		const h = hearts[i];
		if (h.delay > 0) {
			h.delay -= dt;
			continue;
		}
		h.age += dt;
		const t = h.age / h.life;

		if (t >= 1) {
			h.mesh.visible = false;
			heartsFree.push(h.mesh);
			hearts.splice(i, 1);
			continue;
		}

		const appear = clamp01(h.age / 150);
		const fadeOut = clamp01((1 - t) / 0.35);
		const reach = easeOutCubic(t) * h.distance * 0.9;

		h.mesh.visible = true;
		h.mesh.position.set(
			Math.cos(h.angle) * reach,
			scareY + Math.sin(h.angle) * reach + t * 0.3,
			0.9
		);
		h.mesh.rotation.z = Math.sin(h.age / 300 + h.phase) * 0.35;
		h.mesh.scale.setScalar(h.size * Math.max(easeOutBack(appear), 0.001));
		h.mesh.material.opacity = Math.min(appear, fadeOut) * 0.95;
	}
}

// ---- Ojos ----

function checkEyes(dt) {
	if (typeof face === 'undefined' || !face) return;

	const eyes = Math.min(face.blinkLeft, face.blinkRight);
	if (eyes > eyesClosedAt) {
		eyesClosed = true;
		openTimer = 0;
	} else if (eyes < eyesOpenAt) {
		openTimer += dt;
		if (openTimer >= 120) eyesClosed = false;
	} else {
		openTimer = 0;
	}

	// Sonrisa ligera, con un poquito de perdón por si la cámara la pierde un instante
	const smile = face.smile || 0;
	if (smile > smileOnAt) {
		smiling = true;
		smileLost = 0;
	} else if (smile < smileOffAt) {
		smileLost += dt;
		if (smileLost >= smileGrace) smiling = false;
	}

	if (phase === 'idle') {
		const ready = eyesClosed && smiling && face.jawOpen < mouthOpenMax;
		if (ready) {
			closedTime += dt;
			if (closedTime >= scareHold) {
				closedTime = 0;
				startScare();
			}
		} else {
			// Si algo se corta un instante, el contador baja despacio en vez de volver a cero
			closedTime = Math.max(0, closedTime - dt * 2);
		}
	} else if (phase === 'scared' && !eyesClosed) {
		startLove();
	}
}

// ---- Eventos ----

function update(event) {
	const dt = event.delta;
	clock += dt;
	checkEyes(dt);
	updatePanda(dt);
	updateHearts(dt);
	updateSlogan(dt);
}

function stop(event) {
	stopSound(soundScare);
}

function faceLost(event) {
	stopSound(soundScare);
	phase = 'idle';
	closedTime = 0;
	eyesClosed = false;
	smiling = false;
	smileLost = 0;
	openTimer = 0;
	pandaProgress = 0;
	sloganAge = 99999;
	if (sloganMesh) sloganMesh.visible = false;
	if (pandaMesh) pandaMesh.visible = false;
	for (const h of hearts) h.age = h.life;
}

