// Cejas: al subir las cejas cambia el color de la nariz y de las orejas
// Los colores se pintan encima de tus PNG (conservan su forma y sus sombras)
const palette = [
	'#ff6f91', // rosado lichi
	'#ff9f5a', // durazno
	'#ffd23f', // limón
	'#ff4d6d', // fresa
	'#8fdc6a', // hoja de té
	'#c78bff'  // morado suave
];
const holdAfterLower = 350;  // ms que se queda el color después de bajar las cejas
const earsName = 'Orejas';
const soundBrows = loadSound('assets/cejas.mp3');   // suena cuando suben las cejas y cambian los colores
const noseName = 'Nariz';

let ears = null;
let nose = null;
let earsOriginal = null;
let noseOriginal = null;
const earsTextures = [];
const noseTextures = [];
let ready = false;
let raised = false;
let applied = false;
let holdTimer = 0;
let lastEars = -1;

// ---- Sonidos (los mp3 están en la carpeta assets) ----

function loadSound(file) {
	try {
		const audio = new Audio(file);
		audio.preload = 'auto';
		return audio;
	} catch (e) {
		return null;
	}
}

function playSound(audio) {
	if (!audio) return;
	try {
		audio.currentTime = 0;
		const result = audio.play();
		if (result && result.catch) result.catch(() => {});
	} catch (e) {}
}

function stopSound(audio) {
	if (!audio) return;
	try {
		audio.pause();
		audio.currentTime = 0;
	} catch (e) {}
}

function imageSize(image) {
	return [image.naturalWidth || image.width || 0, image.naturalHeight || image.height || 0];
}

// Pinta el PNG con un color. keepShading = true conserva las sombras y brillos (orejas)
function recolor(image, hex, keepShading) {
	const [w, h] = imageSize(image);
	const canvas = document.createElement('canvas');
	canvas.width = w;
	canvas.height = h;
	const ctx = canvas.getContext('2d');
	ctx.drawImage(image, 0, 0);
	const data = ctx.getImageData(0, 0, w, h);
	const px = data.data;

	const r0 = parseInt(hex.slice(1, 3), 16);
	const g0 = parseInt(hex.slice(3, 5), 16);
	const b0 = parseInt(hex.slice(5, 7), 16);

	let avg = 1;
	if (keepShading) {
		let sum = 0, count = 0;
		for (let i = 0; i < px.length; i += 4) {
			if (px[i + 3] > 200) {
				sum += 0.299 * px[i] + 0.587 * px[i + 1] + 0.114 * px[i + 2];
				count++;
			}
		}
		avg = Math.max(1, sum / Math.max(1, count));
	}

	for (let i = 0; i < px.length; i += 4) {
		if (px[i + 3] === 0) continue;
		let f = 1;
		if (keepShading) {
			const lum = 0.299 * px[i] + 0.587 * px[i + 1] + 0.114 * px[i + 2];
			f = Math.min(1.5, Math.max(0.6, 0.6 + 0.4 * lum / avg));
		}
		px[i] = Math.min(255, r0 * f);
		px[i + 1] = Math.min(255, g0 * f);
		px[i + 2] = Math.min(255, b0 * f);
	}
	ctx.putImageData(data, 0, 0);
	return canvas;
}

function makeTexture(canvas, original) {
	const texture = new THREE.CanvasTexture(canvas);
	texture.colorSpace = original.colorSpace;
	texture.flipY = original.flipY;
	texture.wrapS = original.wrapS;
	texture.wrapT = original.wrapT;
	texture.repeat.copy(original.repeat);
	texture.offset.copy(original.offset);
	texture.center.copy(original.center);
	texture.rotation = original.rotation;
	return texture;
}

// Prepara todos los colores una sola vez (espera a que las imágenes estén cargadas)
function prepare() {
	ears = scene.getObjectByName(earsName);
	nose = scene.getObjectByName(noseName);
	if (!ears || !nose || !ears.material.map || !nose.material.map) return;

	const earsImage = ears.material.map.image;
	const noseImage = nose.material.map.image;
	if (!earsImage || !noseImage || imageSize(earsImage)[0] === 0 || imageSize(noseImage)[0] === 0) {
		setTimeout(prepare, 300);
		return;
	}

	earsOriginal = ears.material.map;
	noseOriginal = nose.material.map;
	for (const color of palette) {
		earsTextures.push(makeTexture(recolor(earsImage, color, true), earsOriginal));
		noseTextures.push(makeTexture(recolor(noseImage, color, false), noseOriginal));
	}
	ready = true;
}

function apply() {
	if (!ready) return;
	// Un color para las orejas y otro distinto para la nariz
	let e = Math.floor(Math.random() * palette.length);
	if (e === lastEars) e = (e + 1) % palette.length;
	lastEars = e;
	const n = (e + 1 + Math.floor(Math.random() * (palette.length - 1))) % palette.length;

	ears.material.map = earsTextures[e];
	ears.material.needsUpdate = true;
	nose.material.map = noseTextures[n];
	nose.material.needsUpdate = true;
	applied = true;
}

function restore() {
	if (!ready || !applied) return;
	ears.material.map = earsOriginal;
	ears.material.needsUpdate = true;
	nose.material.map = noseOriginal;
	nose.material.needsUpdate = true;
	applied = false;
}

function start() {
	prepare();
}

function update(event) {
	if (!raised && applied) {
		holdTimer -= event.delta;
		if (holdTimer <= 0) restore();
	}
}

function browRaise(event) {
	raised = true;
	apply();
	playSound(soundBrows);
}

function browLower(event) {
	raised = false;
	holdTimer = holdAfterLower;
}

function stop(event) {
	stopSound(soundBrows);
}

function faceLost(event) {
	raised = false;
	stopSound(soundBrows);
	restore();
}

