// Panda + corazones: aparecen mientras la persona guiña un ojo
const pandaOpacity = 0.55;   // 1 = sólido, 0.3 = muy transparente (para que se vea la cara)
const pandaIn = 400;         // ms que tarda el panda en crecer desde el centro de la cara
const pandaOut = 500;        // ms que tarda en encogerse al dejar de guiñar
const heartsIn = 450;        // ms que tardan en surgir los corazones
const heartsOut = 500;       // ms que tardan en desaparecer
const holdAfterWink = 600;   // ms que espera antes de empezar a esconderse
const winkConfirm = 200;     // ms que el guiño debe mantenerse para contar (así no se confunde al cerrar los dos ojos)
const hideWhilePanda = ['Nariz', 'Orejas', 'rosado 1', 'Rosado 2'];

// Corazoncitos que caen de arriba hacia abajo mientras dura el guiño
const rainEvery = [180, 380]; // cada cuántos ms sale uno nuevo (mínimo, máximo). Más alto = menos corazones
const rainMax = 14;           // máximo de corazoncitos al mismo tiempo
const rainLife = [2200, 3200];// cuánto tarda cada uno en caer (ms). Más alto = caen más lento
const rainSize = [0.09, 0.17];// tamaño (1 = ancho de la cara)
const rainTop = 1.0;          // altura desde donde salen
const rainBottom = -0.9;      // altura hasta donde caen
const rainColors = ['#ff6f91', '#ff8fab', '#ffb3c6', '#ff4d6d'];

let winking = false;
let wasWinking = false;
let winkRaw = false;         // guiño detectado en este instante (todavía sin confirmar)
let winkTimer = 0;
let bothClosed = false;
let holdTime = 0;
let progress = 0;            // 0 = corazones escondidos, 1 = corazones completos
let pandaProgress = 0;       // 0 = panda escondido, 1 = panda completo
let pandaScale = null;
let clock = 0;
let hearts = null;
let heartsScale = null;
let heartsPos = null;
let rainTimer = 0;
const rainActive = [];
const rainFree = [];
const rainTextures = [];

// ---- Sonido (el archivo está en la carpeta assets) ----
const soundWink = loadSound('assets/guino.mp3');   // suena cuando se confirma el guiño

function loadSound(file) {
	try {
		const audio = new Audio(file);
		audio.preload = 'auto';
		return audio;
	} catch (e) {
		return null;
	}
}

function playSound(audio) {
	if (!audio) return;
	try {
		audio.currentTime = 0;
		const result = audio.play();
		if (result && result.catch) result.catch(() => {});
	} catch (e) {}
}

function stopSound(audio) {
	if (!audio) return;
	try {
		audio.pause();
		audio.currentTime = 0;
	} catch (e) {}
}

function easeOutCubic(x) {
	return 1 - Math.pow(1 - x, 3);
}

function easeOutBack(x) {
	const c1 = 1.70158;
	const c3 = c1 + 1;
	return 1 + c3 * Math.pow(x - 1, 3) + c1 * Math.pow(x - 1, 2);
}

function random(range) {
	return range[0] + Math.random() * (range[1] - range[0]);
}

function makeHeartTexture(color) {
	const size = 128;
	const canvas = document.createElement('canvas');
	canvas.width = canvas.height = size;
	const ctx = canvas.getContext('2d');
	const c = size / 2;
	ctx.fillStyle = color;
	ctx.beginPath();
	ctx.moveTo(c, size * 0.88);
	ctx.bezierCurveTo(size * 0.1, size * 0.55, size * 0.05, size * 0.2, c * 0.55, size * 0.15);
	ctx.bezierCurveTo(c * 0.8, size * 0.1, c, size * 0.25, c, size * 0.32);
	ctx.bezierCurveTo(c, size * 0.25, c * 1.2, size * 0.1, c * 1.45, size * 0.15);
	ctx.bezierCurveTo(size * 0.95, size * 0.2, size * 0.9, size * 0.55, c, size * 0.88);
	ctx.fill();
	// Brillito
	ctx.fillStyle = 'rgba(255, 255, 255, 0.55)';
	ctx.beginPath();
	ctx.ellipse(size * 0.3, size * 0.3, size * 0.07, size * 0.045, -0.6, 0, Math.PI * 2);
	ctx.fill();
	const texture = new THREE.CanvasTexture(canvas);
	texture.colorSpace = THREE.SRGBColorSpace;
	return texture;
}

function spawnRainHeart() {
	if (rainActive.length >= rainMax) return;
	if (rainTextures.length === 0) {
		for (const color of rainColors) rainTextures.push(makeHeartTexture(color));
	}

	let mesh = rainFree.pop();
	if (!mesh) {
		mesh = new THREE.Mesh(
			new THREE.PlaneGeometry(1, 1),
			new THREE.MeshBasicMaterial({ transparent: true, depthWrite: false, side: THREE.DoubleSide })
		);
		mesh.renderOrder = 3;
		scene.add(mesh);
	}

	mesh.material.map = rainTextures[Math.floor(Math.random() * rainTextures.length)];
	mesh.material.needsUpdate = true;
	mesh.visible = true;

	rainActive.push({
		mesh,
		age: 0,
		life: random(rainLife),
		x: random([-0.8, 0.8]),
		size: random(rainSize),
		sway: random([0.03, 0.09]),
		phase: Math.random() * Math.PI * 2,
		tilt: random([0.2, 0.5])
	});
}

function updateRain(dt, show) {
	if (show) {
		rainTimer -= dt;
		if (rainTimer <= 0) {
			spawnRainHeart();
			rainTimer = random(rainEvery);
		}
	}

	for (let i = rainActive.length - 1; i >= 0; i--) {
		const h = rainActive[i];
		h.age += dt;
		const t = h.age / h.life;

		if (t >= 1) {
			h.mesh.visible = false;
			rainFree.push(h.mesh);
			rainActive.splice(i, 1);
			continue;
		}

		const appear = Math.min(1, h.age / 250);
		const fadeOut = Math.min(1, (h.life - h.age) / 500);
		const pop = easeOutBack(appear);

		h.mesh.position.set(
			h.x + Math.sin(h.age / 450 + h.phase) * h.sway,
			rainTop + (rainBottom - rainTop) * t,
			0.5
		);
		h.mesh.rotation.z = Math.sin(h.age / 600 + h.phase) * h.tilt;
		h.mesh.scale.setScalar(h.size * Math.max(pop, 0.001));
		h.mesh.material.opacity = Math.min(appear, fadeOut) * 0.95;
	}
}

function start() {
	pandaScale = this.scale.clone();
	this.visible = false;
	this.material.transparent = true;
	this.material.opacity = 0;

	hearts = scene.getObjectByName('Corazones');
	if (hearts) {
		heartsScale = hearts.scale.clone();
		heartsPos = hearts.position.clone();
		hearts.material.transparent = true;
		hearts.visible = false;
	}
}

function update(event) {
	const dt = event.delta;
	clock += dt;

	// El guiño cuenta solo si se mantiene un momento. Si se cierran los dos ojos, se cancela de una vez
	if (bothClosed) {
		winkTimer = 0;
		winking = false;
		holdTime = 0;
	} else {
		winkTimer = winkRaw ? winkTimer + dt : 0;
		winking = winkTimer >= winkConfirm;
	}

	// El sonido suena una sola vez, justo cuando el guiño se confirma
	if (winking && !wasWinking) playSound(soundWink);
	wasWinking = winking;

	if (winking) holdTime = holdAfterWink;
	else holdTime = Math.max(0, holdTime - dt);
	const show = winking || holdTime > 0;

	// Panda: crece desde el centro de la cara y se encoge al salir
	const pandaStep = dt / (show ? pandaIn : pandaOut);
	pandaProgress = Math.min(1, Math.max(0, pandaProgress + (show ? pandaStep : -pandaStep)));
	const grow = easeOutCubic(pandaProgress);

	this.visible = pandaProgress > 0;
	this.scale.copy(pandaScale).multiplyScalar(Math.max(grow, 0.001));
	this.material.opacity = pandaOpacity * Math.min(1, pandaProgress * 2);

	// Cuando el panda ya cubre buena parte de la cara, se esconden orejas, nariz y rosados
	for (const name of hideWhilePanda) {
		const object = scene.getObjectByName(name);
		if (object) object.visible = pandaProgress < 0.5;
	}

	// Corazoncitos que caen
	updateRain(dt, show);

	// Corazones: surgen desde abajo con un pequeño rebote y flotan
	if (hearts) {
		const step = dt / (show ? heartsIn : heartsOut);
		progress = Math.min(1, Math.max(0, progress + (show ? step : -step)));

		hearts.visible = progress > 0;
		hearts.scale.copy(heartsScale).multiplyScalar(Math.max(easeOutBack(progress), 0.001));
		hearts.position.set(
			heartsPos.x,
			heartsPos.y - (1 - progress) * 0.3 + Math.sin(clock / 300) * 0.02 * progress,
			heartsPos.z
		);
		hearts.material.opacity = Math.min(1, progress * 1.5);
	}
}

function faceUpdate(event) {
	const left = face.blinkLeft;
	const right = face.blinkRight;
	// Guiño: un ojo cerrado y el otro abierto (un parpadeo normal cierra los dos)
	winkRaw = (left > 0.6 && right < 0.35) || (right > 0.6 && left < 0.35);
	bothClosed = left > 0.6 && right > 0.6;
}

function stop(event) {
	stopSound(soundWink);
}

function faceLost(event) {
	stopSound(soundWink);
	winking = false;
	wasWinking = false;
	winkRaw = false;
	winkTimer = 0;
	bothClosed = false;
	holdTime = 0;
	for (const h of rainActive) h.age = h.life;
}
